mapper.select:
SELECT p.PLAYLIST_ID AS "playlistId",
p.TITLE AS "title"
FROM COMBINATION c
JOIN REC_PLAYLIST p ON p.COMBINATION_ID = c.COMBINATION_ID
WHERE c.GENRE_CODE = #{genre}
AND (
SELECT COUNT(*)
FROM COMBINATION_MOOD m
WHERE m.COMBINATION_ID = c.COMBINATION_ID
) = #{moodCount}
AND (
SELECT COUNT(*)
FROM COMBINATION_MOOD m
WHERE m.COMBINATION_ID = c.COMBINATION_ID
AND m.MOOD_CODE IN

    #{mood}

) = #{moodCount}
ORDER BY p.DISPLAY_ORDER, p.PLAYLIST_ID
FETCH FIRST 10 ROWS ONLY
